//! Generated by `rust-anything app wire` from rust-anything.json; it is rewritten on every wire.

use std::collections::HashMap;

use axum::Router;
use axum::extract::{Request, State};
use axum::response::Response;
use axum::routing::get;

use crate::original::{self, Original};

mod staticassets;

/// `RUST_ANYTHING_UNIT_<NAME>=original` sends that unit back to the original.
fn sent_to_original(unit: &str) -> bool {
    std::env::var(format!("RUST_ANYTHING_UNIT_{unit}")).is_ok_and(|v| v == "original")
}

pub fn router() -> Router<Original> {
    Router::new()
        .route("/", get(route_1).fallback(original::proxy))
        .route("/index.html", get(route_0).fallback(original::proxy))
        .fallback(original::proxy)
}

async fn route_0(State(original): State<Original>, req: Request) -> Response {
    if sent_to_original("STATICASSETS") {
        return original::proxy(State(original), req).await;
    }
    staticassets::handle("GET /index.html", HashMap::new(), req).await
}

async fn route_1(State(original): State<Original>, req: Request) -> Response {
    if sent_to_original("STATICASSETS") {
        return original::proxy(State(original), req).await;
    }
    staticassets::handle("GET /", HashMap::new(), req).await
}
